prompt:
Create unit `tasks` and implement `spread`: the largest element minus the smallest element, for a non-empty array whose elements are all between -1000 and 1000. The contract must state that the result is >= 0. Reuse the existing library (see `query units`) where it helps.

Required signature (in unit `tasks`):
fn spread(a: &[i64]) -> (r: i64)

reference.code:
spec fn small_nonempty(a: &[i64]) -> bool { a.len() > 0 && (forall|k: usize| k < a.len() ==> -1000 <= #[trigger] a[k] && a[k] <= 1000) }

spec fn hi_lo(hi: i64, lo: i64) -> bool { -1000 <= lo && lo <= hi && hi <= 1000 }

spec fn nonneg(r: i64) -> bool { r >= 0 }

#[effects(pure)]
#[uses(small_nonempty, hi_lo, nonneg, math::is_max2, math::is_min2)]
fn spread(a: &[i64]) -> (r: i64)
    requires small_nonempty(a),
    ensures nonneg(r),
{
    let mut hi: i64 = a[0];
    let mut lo: i64 = a[0];
    let mut k: usize = 1;
    while k < a.len()
        invariant 1 <= k, k <= a.len(), hi_lo(hi, lo),
        decreases a.len() - k,
    {
        hi = math::max2(hi, a[k]);
        lo = math::min2(lo, a[k]);
        k = k + 1;
    }
    hi - lo
}
